#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

/**
 * Problem: 10603 - Cutting Sticks
 * 
 * 解題思路：
 * 1. 這是一個典型的區間動態規劃 (Interval DP) 問題。
 * 2. 給定長度 L 的木棍和 n 個切割點，設切割點座標為 c_1, c_2, ..., c_n。
 * 3. 加上邊界點 c_0 = 0 和 c_{n+1} = L。
 * 4. 令 dp[i][j] 為切割區間 [c_i, c_j] 的最小成本。
 * 5. 轉移方程：dp[i][j] = (c_j - c_i) + min(dp[i][k] + dp[k][j])，其中 i < k < j。
 */

int main() {
    int L;
    while (cin >> L && L != 0) {
        int n;
        cin >> n;
        vector<int> c(n + 2);
        c[0] = 0;
        for (int i = 1; i <= n; ++i) cin >> c[i];
        c[n + 1] = L;

        int m = n + 2;
        vector<vector<int>> dp(m, vector<int>(m, 0));

        // len 是區間包含的切割點數量 + 1 (即 c 陣列的索引跨度)
        for (int len = 2; len < m; ++len) {
            for (int i = 0; i + len < m; ++i) {
                int j = i + len;
                int min_cost = 1e9;
                for (int k = i + 1; k < j; ++k) {
                    min_cost = min(min_cost, dp[i][k] + dp[k][j]);
                }
                dp[i][j] = (c[j] - c[i]) + min_cost;
            }
        }

        cout << "The minimum cutting is " << dp[0][m - 1] << "." << endl;
    }
    return 0;
}
